<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $notification = $args['notification']; $is_new = ! empty( $notification->is_new ); ?><article class="sd-notification-item <?php echo $is_new ? 'is-unread' : ''; ?>" data-sd-notification="<?php echo esc_attr( $notification->id ); ?>"><div><span class="sd-notification-type"><?php echo esc_html( sd_notification_label( $notification ) ); ?></span><p><?php echo esc_html( ! empty( $notification->content ) ? wp_strip_all_tags( $notification->content ) : sd_notification_label( $notification ) ); ?></p><time><?php echo esc_html( ! empty( $notification->date_notified ) ? $notification->date_notified : '' ); ?></time></div><div class="sd-notification-item-actions"><a href="<?php echo esc_url( sd_notification_url( $notification ) ); ?>" data-sd-notification-open><?php esc_html_e( 'Open', 'social-discovery' ); ?></a><?php if ( $is_new ) : ?><button type="button" data-sd-notification-state="read"><?php esc_html_e( 'Mark read', 'social-discovery' ); ?></button><?php endif; ?></div></article>
